//! Shared fixture locations for the gate suites.
//!
//! Oracle records are generated by `projects/vutex.ts/examples/oracle` and
//! checked in under `records/`, so the gates read the generators' own output
//! instead of keeping a second copy that can drift.

use std::{
    path::{Path, PathBuf},
    sync::Once,
};

/// Directory holding the oracle records and the shared gate corpora.
pub fn oracle_records() -> PathBuf {
    repo_root().join("projects").join("vutex.ts").join("examples").join("oracle").join("records")
}

/// Schema that the oracle records are validated against.
#[allow(dead_code)]
pub fn fixture_schema() -> PathBuf {
    repo_root().join("projects").join("vutex.ts").join("examples").join("oracle").join("fixture-schema.json")
}

/// Latin Modern Math asset shipped with the repository.
#[allow(dead_code)]
pub fn math_font() -> PathBuf {
    math_fonts_dir().join("LatinModernMath-Regular.otf")
}

/// Directory holding the host math faces.
#[allow(dead_code)]
pub fn math_fonts_dir() -> PathBuf {
    repo_root().join("projects").join("vutex.rs").join("fonts")
}

/// Install the host math faces as the process-wide default.
///
/// Math bytes are host-owned, so the gates read the pack from the repository
/// fonts directory and register it once per test binary. Without this the
/// layout pipeline reports that no math font is installed.
#[allow(dead_code)]
pub fn ensure_math_fonts() {
    static INSTALL: Once = Once::new();
    INSTALL.call_once(|| {
        let dir = math_fonts_dir();
        let pack = document_fonts::MathFontPack::load_from(&dir)
            .unwrap_or_else(|e| panic!("failed to load the math font pack from {}: {e}", dir.display()));
        document_fonts::install_math_fonts(&pack);
    });
}

/// Repository root, four levels above this crate.
fn repo_root() -> &'static Path {
    Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().nth(4).expect("the gate crate sits four levels below the repository root")
}
